import{_ as t,o,c as i,a0 as a}from"./chunks/framework.ZNXClGez.js";const u=JSON.parse('{"title":"Policy Engine","description":"","frontmatter":{},"headers":[],"relativePath":"guide/contributing/policy-engine.md","filePath":"guide/contributing/policy-engine.md"}'),n={name:"guide/contributing/policy-engine.md"};function s(c,e,r,d,l,p){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="policy-engine" tabindex="-1">Policy Engine <a class="header-anchor" href="#policy-engine" aria-label="Permalink to &quot;Policy Engine&quot;">​</a></h1><p>The policy engine lives in <code>packages/access</code> and is consumed by <code>apps/server-core</code> (request authorization), <code>packages/client-web-kit</code> (UI permission checks) and any downstream application. This page explains its evaluation model and how to extend it — read it before touching <code>packages/access/src/policy/**</code> or the server-core evaluator in <code>apps/server-core/src/core/security/policy/</code>.</p><h2 id="two-layer-evaluation" tabindex="-1">Two-layer evaluation <a class="header-anchor" href="#two-layer-evaluation" aria-label="Permalink to &quot;Two-layer evaluation&quot;">​</a></h2><p>A permission check evaluates two layers, both of which must pass:</p><ol><li><strong>Permission-level policies</strong> — the policies attached to the permission itself via the <code>auth_permission_policies</code> junction (for built-in permissions, usually the <code>system.default</code> composite: <code>system.identity</code> + <code>system.permission-binding</code>).</li><li><strong>Per-grant factors</strong> — enforced inside <code>system.permission-binding</code> (the server-core <code>PermissionBindingPolicyEvaluator</code>): each grant&#39;s coarse realm reach (<code>realmScope</code>) and its optional junction policy (<code>policyId</code>). An actor&#39;s multiple grants for one permission form a <strong>disjunction</strong> — access is granted iff some grant passes both of its own factors.</li></ol><h2 id="tri-state-evaluation" tabindex="-1">Tri-state evaluation <a class="header-anchor" href="#tri-state-evaluation" aria-label="Permalink to &quot;Tri-state evaluation&quot;">​</a></h2><p>The engine is tri-state: a policy settles <strong>true</strong>, settles <strong>false</strong>, or stays <strong>pending</strong> when the data it needs is not in the evaluation bag yet (<code>PolicyEvaluationResult.pending</code>, riding on <code>success: false</code> so any consumer that ignores the flag fails closed).</p><ul><li>Every evaluator declares its data needs via <code>requires?(value)</code> — the <code>PolicyData</code> keys it needs before it can settle (e.g. <code>identity</code>, <code>attributes</code>). The engine checks the declaration <strong>before</strong> invoking the evaluator; a missing key yields a pending <code>DATA_MISSING</code> result instead of an evaluation against missing data.</li><li>The composite algebra treats pending children as <em>unknown</em>: they are never counted and never masked to a settled value, and the composite settles despite them only when no resolution could change the outcome. <code>invert</code> is <strong>never applied to a pending result</strong> — unknown stays unknown under negation.</li><li><code>preEvaluate</code> (the pre-flight gate) is <em>derived</em> from data availability: it passes <code>pendingPolicies: &#39;permit&#39;</code>, so a pending tree passes the gate and only a tree that settles false with the current bag denies. The full <code>evaluate()</code> with the enriched bag remains the authority (pending ⇒ deny there).</li></ul><p>There is <strong>no hand-maintained exclusion list</strong> anymore — a new policy type places itself by shipping <code>requires()</code>, with zero engine edits.</p><h2 id="condition-lowering-where-pushdown" tabindex="-1">Condition lowering (WHERE pushdown) <a class="header-anchor" href="#condition-lowering-where-pushdown" aria-label="Permalink to &quot;Condition lowering (WHERE pushdown)&quot;">​</a></h2><p>An evaluator may additionally implement <code>toCondition?(value, ctx)</code> — express the policy as a rapiq <code>ICondition</code> over row attributes, partial-evaluated against the knowns bag (e.g. the actor&#39;s realm baked into a realm-match condition). The contract is <strong>exactness</strong>: a row satisfies the condition iff the policy settles true with that row&#39;s attributes. Return <code>null</code> (or throw) when a configuration is not expressible — it then stays a per-row post-check, which is always sound.</p><p>Lowering rides the same evaluation walk, opt-in via the evaluation-context flag <code>withConditions</code> (default off, so <code>evaluate</code>/<code>preEvaluate</code> hot paths never pay it): the engine attaches <code>result.condition</code> when a leaf pends, and the composite composes residuals structurally — settled children drop out as identity elements, <code>AND</code>/<code>OR</code> residuals compose <strong>all-or-nothing per node</strong> (pushing a single <code>OR</code> disjunct would wrongly exclude rows), and <code>invert</code> wraps the residual symbolically via rapiq&#39;s <code>not()</code> (null-inclusive complement, so pushdown and in-memory post-checks agree on null-bearing rows).</p><h2 id="adding-a-policy-type" tabindex="-1">Adding a policy type <a class="header-anchor" href="#adding-a-policy-type" aria-label="Permalink to &quot;Adding a policy type&quot;">​</a></h2><ol><li>Create <code>packages/access/src/policy/built-in/&lt;name&gt;/</code> with <code>types.ts</code> (config type), <code>validator.ts</code>, <code>evaluator.ts</code> (+ barrel <code>index.ts</code>), mirroring an existing sibling.</li><li>The evaluator implements <code>IPolicyEvaluator</code>: <ul><li><code>evaluate(value, ctx)</code> — settle against the bag; use <code>maybeInvertPolicyOutcome</code> only on genuine outcomes (never on non-evaluations or pendings).</li><li><code>requires(value)</code> — the data keys the config needs; may be config-dependent (see the realm-match evaluator&#39;s scope vs. attribute mode).</li><li><code>toCondition(value, ctx)</code> — optional, only when the policy is expressible over row attributes.</li></ul></li><li>Register the type in <code>BuiltInPolicyType</code>, <code>BuiltInPolicyTypeMap</code> (<code>built-in/types.ts</code> — without this <code>definePolicyWithType</code> cannot author it) and <code>PolicyDefaultEvaluators</code> (<code>policy/constants.ts</code>).</li><li>Server-side persistence: add the config&#39;s attribute validators in <code>@authup/core-kit</code>&#39;s policy validator so the API can persist it, and extend the kit&#39;s policy form components for the UI.</li><li>Tests live in <code>packages/access/test/unit/policy/</code> — pin settled/pending/inverted behavior, and when <code>toCondition</code> exists, pin <strong>semantic parity</strong>: compile the condition with <code>@rapiq/adapter-memory</code> and assert the predicate equals full evaluation row by row (see <code>to-condition.spec.ts</code>).</li></ol><h2 id="where-things-live" tabindex="-1">Where things live <a class="header-anchor" href="#where-things-live" aria-label="Permalink to &quot;Where things live&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concern</th><th>Location</th></tr></thead><tbody><tr><td>Engine, tri-state gate</td><td><code>packages/access/src/policy/engine/module.ts</code></td></tr><tr><td>Built-in evaluators</td><td><code>packages/access/src/policy/built-in/*/evaluator.ts</code></td></tr><tr><td>Composite algebra</td><td><code>packages/access/src/policy/built-in/composite/evaluator.ts</code></td></tr><tr><td>Permission evaluator (<code>evaluate</code>/<code>preEvaluate</code>)</td><td><code>packages/access/src/permission/evaluator/module.ts</code></td></tr><tr><td>Grant aggregation &amp; dominance</td><td><code>packages/access/src/permission/helpers/</code></td></tr><tr><td>Realm reach (<code>realmScope</code>)</td><td><code>packages/access/src/permission/realm-scope/</code></td></tr><tr><td>Server-core binding evaluator (Layer 2)</td><td><code>apps/server-core/src/core/security/policy/evaluator.ts</code></td></tr></tbody></table><p>The authoritative, always-current deep-dive is the repository&#39;s agent documentation: <a href="https://github.com/authup/authup/blob/master/.agents/architecture.md" target="_blank" rel="noreferrer"><code>.agents/architecture.md</code></a> (sections <em>Policy-Permission Model</em> and <em>preEvaluate is derived from data availability</em>).</p>',17)])])}const g=t(n,[["render",s]]);export{u as __pageData,g as default};
